head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vCreditValuTpCd = 1;
scwin.vCheck_RcvYn = '';
scwin.vDuplStdCdCnt = 0;
scwin.vEtcChgStdCdCnt = 0;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.vCreditValuInstNm = '', scwin.vSameGrdYn = '';
scwin.vProcStdCdCnt = 0, scwin.vAcptDataCnt = 0;
scwin.btnStat = new Object();
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리(수신내역/처리완료내역)
        $c.bns.BnsPanelToGroupBox(pnl_Recv);
        $c.bns.BnsPanelToGroupBox(pnl_Proc);
        $c.bns.BnsPanelToGroupBox(pnl_Srch);
        $c.bns.BnsPanelToGroupBox(pnl_Srch2);
        btn_rcvConfrm.hide();
        if (js_usr_tp_cd === '1') {
            // 운영자이면
            btn_rcvConfrm.show("");
        }
        tab_List.setSelectedTabIndex(1);
        txt_MiRcvInst.setValue('수신평가정보가 없음');

        // 수신일 현재일자로 설정
        edt_RcvDd.setValue(scwin.vCurDate);

        // 수신일 시작일, 종료일 현재일자로 설정
        edt_StartDd.setValue(scwin.vCurDate);
        edt_EndDd.setValue(scwin.vCurDate);
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        scwin.vCreditValuTpCd = nIndex;
        if (scwin.vCreditValuTpCd === 2) {
            scwin.listSyncProc();
        } else {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name img_RcvDd_onclick
 * @description img_RcvDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_RcvDd_onclick = function() {
    try {
        popUpCalendar2(edt_RcvDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.img_RcvDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_CreditValuInstNm_onselchange
 * @description cmb_CreditValuInstNm onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_CreditValuInstNm_onselchange = function() {
    try {
        scwin.vCreditValuInstNm = cmb_CreditValuInstNm.getValue();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.cmb_CreditValuInstNm_onselchange" });
    }
};

/**
 * @method
 * @name cmb_SameGrdYn_onselchange
 * @description cmb_SameGrdYn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_SameGrdYn_onselchange = function() {
    try {
        scwin.vSameGrdYn = cmb_SameGrdYn.getValue();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.cmb_SameGrdYn_onselchange" });
    }
};

/**
 * @method
 * @name btn_Srch_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Srch_onclick = function() {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.btn_Srch_onclick" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        const vStrtDd = dts_DtlInfo.getCellData(1, "STRT_DD");
        const vMiRcvInst = dts_DtlInfo.getCellData(1, "MI_RCV_INST");
        if (rowcount > 0) {
            txt_MiRcvInst.setValue((vMiRcvInst === '') ? '평가사 수신완료' : '미수신평가사 : ' + vMiRcvInst);
            scwin.setBtnProcStat(vStrtDd); // 처리완료 버튼 활성/비활성 설정

        } else {
            txt_MiRcvInst.setValue('수신평가정보가 없음');
        }
        scwin.listSync(); // 신용평가 수신정보 내역 조회
        scwin.srtListSync(); // 신용평가 수신이력 조회
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        scwin.setBgColorList(); // 그리드 배경색 설정
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_SrtInfo_OnLoadCompleted
 * @description dts_SrtInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_SrtInfo_OnLoadCompleted = function(rowcount) {
    try {
        dts_SrtInfo.setRowPosition(0, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_SrtInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_RcvYn_OnLoadCompleted
 * @description dts_RcvYn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_RcvYn_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vCheck_RcvYn = dts_RcvYn.getCellData(1, "TEXT");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_RcvYn_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ProcStdCd_OnLoadCompleted
 * @description dts_ProcStdCd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProcStdCd_OnLoadCompleted = async function(rowcount) {
    try {
        scwin.vProcStdCdCnt = rowcount;
        await scwin.procsComplt(); // 접수처리
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.dts_ProcStdCd_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_EtcChgStdCd_OnLoadCompleted
 * @description dts_EtcChgStdCd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EtcChgStdCd_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vEtcChgStdCdCnt = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_EtcChgStdCd_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_DuplStdCd_OnLoadCompleted
 * @description dts_DuplStdCd 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DuplStdCd_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vDuplStdCdCnt = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_DuplStdCd_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        if (row === 0) return;
        if (colid === "BND_ISU_NM") {
            scwin.fn_GetPar = scwin.passData;
            scwin.fn_SetPar = '';
            await scwin.popCreditValuInstGrd(lbl_RcvDd);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name btn_Proc_onclick
 * @description 「처리완료」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Proc_onclick = function() {
    try {
        if (scwin.btnStat.Proc === 'dis') return;
        scwin.getRcvYn(); // 평가사로부터 수신여부 체크
        scwin.duplStdCd(); // 수신종목 중복체크
        scwin.etcChgStdCd(); // 수신종목과 기타변경 중복조치 종목 확인
        scwin.listStdCd(); // 수신평가등급을 처리완료하기 위한 종목 내역 조회
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.btn_Proc_onclick" });
    }
};

/**
 * @method
 * @name btn_ToExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToExcel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDBNS30200.xml', SCREN_PROCS_TP_CD_07, '');
        let fileNm = scwin.vCurDate + '_' + '신용평가등급 수신내역';
        $c.data.downloadGridViewExcel(grd_List, {fileName: "신용평가 수신 및 처리(수신내역)", type: 8});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.btn_ToExcel_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        dts_DtlInfo.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.trs_Save_OnFail" });
