    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.dts_ListProc_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_StartDd_onclick
 * @description img_StartDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StartDd_onclick = function() {
    try {
        popUpCalendar2(edt_StartDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.img_StartDd_onclick" });
    }
};

/**
