    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.img_EndDd_onclick" });
    }
};

/**
 * @method
 * @name txb_StdCd_onkeypress
 * @description txb_StdCd onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_StdCd_onkeypress = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
            if (window.event.keyCode === 13) scwin.listSyncProc();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.txb_StdCd_onkeypress" });
    }
};

/**
 * @method
 * @name btn_Srch2_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Srch2_onclick = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
            scwin.listSyncProc();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.btn_Srch2_onclick" });
    }
};

/**
 * @method
 * @name grd_List_Proc_OnClick
 * @description grd_List_Proc 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
