        $c.data.downloadGridViewExcel(grd_List_Proc, {fileName: "신용평가 수신 및 처리(처리완료내역)", type: 8});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.btn_ToExcel2_onclick" });
