 */
scwin.img_IsuNm_onclick = function() {
    try {
        scwin.showIsu(txb_StdCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.img_IsuNm_onclick" });
    }
};

/**
 * @method
 * @name txb_StdCd_onkeypress
 * @description txb_StdCd onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_StdCd_onkeypress = function() {
    try {
        if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
            if (window.event.keyCode === 13) scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30200.txb_StdCd_onkeypress" });
    }
