/**
 * @method
 * @name btn_rcvConfrm_onclick
 * @description 「수신확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_rcvConfrm_onclick = async function() {
    try {
        await scwin.popCrdtgrdRcvInfo(grd_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30200.btn_rcvConfrm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 신용평가 수신정보를 조회 한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let dsNm = 'BNS_CLS_CREDIT_INFO';
    let qryId = 'lds.stf.bnscls.select.readCreditValuInstRcv';
    let param = '&{P}V_RCV_DD=' + edt_RcvDd.getValue();
    param += '&{P}V_CREDIT_PROCS_TP_CD=' + scwin.vCreditValuTpCd;
    $c.bns.fn_SearchBns('ULDBNS30200.xml', dts_DtlInfo, dsNm, qryId, param);
};

/**
 * @method
 * @name setBtnProcStat
 * @description 처리완료 버튼 활성/비활성 설정
 * @param {String} vStrtDd vStrtDd
 * @returns {void}
 * @hidden N
 */
scwin.setBtnProcStat = function(vStrtDd) {
    if (vStrtDd !== '') {
        // 처리완료시
        btn_Proc.setBackgroundImage('../img/bns/btn_20_d.gif');
        scwin.btnStat.Proc = 'dis';
    } else {
        if (edt_RcvDd.getValue() === scwin.vCurDate) {
            btn_Proc.setBackgroundImage('../img/bns/btn_20.gif');
            scwin.btnStat.Proc = 'en';
            // 채권매매달력에서 적용일을 구함
            edt_StrtDd.setValue(dts_DtlInfo.getCellData(1, "CLS_STRT_DD"));
        } else {
            btn_Proc.setBackgroundImage('../img/bns/btn_20_d.gif');
            scwin.btnStat.Proc = 'dis';
            edt_StrtDd.setValue('');
        }
    }
};

