/**
 * @method
 * @name setBgColorList
 * @description 수신내역 목록의 배경색 설정
 * @returns {void}
 * @hidden N
 */
scwin.setBgColorList = function() {
    // 그리드 컬럼 ID 구하기
    const arrColID = [];
    for (let i = 0; i < grd_List.getTotalCol(); i++) {
        arrColID.push(grd_List.getColumnID(i));
    }

    // 평가등급 일치여부가 N인 로우의 배경색 Light Yellow로 설정
    for (let j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List, arrColID[j], 'BgColor', "{decode(SAME_GRD_YN,'N','#FFFF99','Y','#FFFFFF',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};

