/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    // 수신완료 체크 : 4개 평가사로부터 모두 수신완료 되어야 한다. 2024.04.22 김효준 추가
    if (scwin.vCheck_RcvYn === 'N') {
        await $c.win.alert("모든 평가사로부터 수신이 완료되지 않았습니다.");
        return false;
    }
    if (edt_StrtDd.getValue() === '') {
        await $c.win.alert("[적용일]을 입력하십시오.");
        return false;
    }
    if (scwin.getDupStdCd() !== '') {
        await $c.win.alert('[' + scwin.getDupStdCd() + '] 중복된 종목이 존재합니다.\n\n 해당 종목의 [한글종목명]을 클릭하여 수신내역을 확인하시기 바랍니다.');
        return false;
    }
    if (scwin.vEtcChgStdCdCnt > 0) {
        await $c.win.alert('금일 수신된 종목중 기타변경 처리완료건이 존재합니다.\n\n동일 종목의 신용등급변경과 기타변경은 중복조치가 불가하니\n\n해당 종목의 처리내용을 확인하시기 바랍니다.');
        return false;
    }

    // 처리완료시 수신내역 유효성체크 (fn_list_sync() 수신내역조회 쿼리에서 이미 유효성체크 결과를 가지고있음)
    if (scwin.checkResData() !== 'Y') {
        await $c.win.alert('금일 수신된 종목중 유효하지 않은 등급이 존재합니다.\n\n수신된 신용평가 등급을 확인하시기 바랍니다.\n\n시스템담당자에게 연락하시기 바랍니다.');
        return false;
    }
};

