/**
 * @method
 * @name procsComplt
 * @description 처리완료 진행
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function() {
    // 필수입력값 체크
    if (await scwin.inputCheck() === false) return;
    let output = '',
        vStdCd = '';
    if (scwin.vProcStdCdCnt === 0) {
        output = "평가등급이 변경된 종목이 없습니다." + "\n\n";
    } else {
        vStdCd = 'EXIST';
        // vStdCd = fn_GetStdCd();

    }
    output += "처리결과 종목은 처리완료내역 탭에서 조회가 가능합니다.";
    output += "\n" + "[신용등급수신] 처리 하시겠습니까?";
    if (!confirm(output)) return;
    let url = "/bns/CreditValu.do?method=processCreditValuRcvProcessComplt";
    url += "&SCREN_ID=" + 'ULDBNS30200.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&STRT_DD=" + edt_StrtDd.getValue();
    url += "&STD_CD=" + vStdCd;

    /**
     *     - 변경된 데이터가 없더라도 데이터셋 전송하여 접수 진행
     */
    dts_DtlInfo.UseChangeInfo = "False";
    dts_ProcStdCd.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};

/**
 * @method
 * @name getDupStdCd
 * @description 수신평가등급을 처리완료하기 위한 표준코드 중 중복코드 반환
 * @returns {void}
 * @hidden N
 */
scwin.getDupStdCd = function() {
    let returnVal = '';
    for (let i = 1; i <= scwin.vDuplStdCdCnt; i++) {
        returnVal += "'" + dts_DuplStdCd.getCellData(i, "TEXT") + "',";
    }
    return returnVal.substring(0, returnVal.length - 1);
};

/**
 * @method
 * @name getStdCd
 * @description 수신평가등급을 처리완료하기 위한 표준코드 반환
 * @returns {void}
 * @hidden N
 */
scwin.getStdCd = function() {
    let returnVal = '';
    for (let i = 1; i <= scwin.vProcStdCdCnt; i++) {
        returnVal += "'" + dts_ProcStdCd.getCellData(i, "TEXT") + "',";
    }
    return returnVal.substring(0, returnVal.length - 1);
};

/**
 * @method
 * @name checkResData
 * @description 처리완료시 수신내역 유효성체크
 * @returns {void}
 * @hidden N
 */
scwin.checkResData = function() {
    let returnVal = 'Y';
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        // alert(dts_List.NameValue(i, "CHECK_AFCHG_GRD_CNT"));
        if (dts_List.getCellData(i, "CHECK_AFCHG_GRD_CNT") === '0') {
            returnVal = 'N';
            break;
        }
    }
    return returnVal;
};

