/**
 * @method
 * @name passData
 * @description 신용평가 수신내역 기록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.passData = function(arrPar) {
    const objDtsData = new Object();
    if (scwin.vCreditValuTpCd === 1) {
        objDtsData.STD_CD = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD");
        objDtsData.BND_ISU_NM = dts_List.getCellData(dts_List.getRowPosition(), "BND_ISU_NM");
    } else {
        objDtsData.STD_CD = dts_ListProc.getCellData(dts_ListProc.getRowPosition(), "STD_CD");
        objDtsData.BND_ISU_NM = dts_ListProc.getCellData(dts_ListProc.getRowPosition(), "BND_ISU_NM");
    }
    scwin.arrPar[0] = {
        STD_CD: objDtsData.STD_CD,
        BND_ISU_NM: objDtsData.BND_ISU_NM
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

